// -----------------------------------------------------------------------------
// Just enough XML for what the FRITZ!Box serves on its AHA-HTTP interface:
// the login answer (`SessionInfo`) and the device list (`devicelist`). These
// documents are small, generated by the box and without mixed content, so a
// short parser builds a tree from them without a dependency (the image stays
// small, the sandbox has 256 MB).
// -----------------------------------------------------------------------------

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

/** Decode the entities and CDATA of a text node; trims it. */
export function decodeXml(text) {
  return String(text ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity) => {
      if (entity[0] === '#') {
        const code =
          entity[1] === 'x' || entity[1] === 'X'
            ? parseInt(entity.slice(2), 16)
            : Number(entity.slice(1));
        return Number.isFinite(code) && code > 0 && code < 0x110000
          ? String.fromCodePoint(code)
          : '';
      }
      return ENTITIES[entity.toLowerCase()] ?? match;
    })
    .trim();
}

/**
 * @typedef {object} XmlNode
 * @property {string} name
 * @property {Record<string, string>} attrs
 * @property {XmlNode[]} children
 * @property {string} text decoded and trimmed text of the element itself
 */

const TOKEN = /<!\[CDATA\[[\s\S]*?\]\]>|<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<![^>]*>|<\/?[^>]+>|[^<]+/g;
const ATTRIBUTE = /([\w:.-]+)\s*=\s*("([^"]*)"|'([^']*)')/g;

/**
 * Parse a document into its root element. Throws on a document that is not
 * XML (an HTML error page, a truncated answer).
 * @returns {XmlNode}
 */
export function parseXml(source) {
  const root = { name: '#document', attrs: {}, children: [], text: '' };
  const stack = [root];
  for (const [token] of String(source ?? '').matchAll(TOKEN)) {
    const top = stack[stack.length - 1];
    if (token.startsWith('<![CDATA[')) {
      top.text += token;
    } else if (token.startsWith('<!') || token.startsWith('<?')) {
      continue;
    } else if (token.startsWith('</')) {
      const name = token.slice(2, -1).trim();
      if (stack.length < 2 || top.name !== name) {
        throw new Error(`Malformed XML: unexpected </${name}>`);
      }
      top.text = decodeXml(top.text);
      stack.pop();
    } else if (token.startsWith('<')) {
      const selfClosing = token.endsWith('/>');
      const inner = token.slice(1, selfClosing ? -2 : -1);
      const name = inner.match(/^[^\s/>]+/)?.[0];
      if (!name) {
        throw new Error('Malformed XML: element without a name');
      }
      const attrs = {};
      for (const match of inner.slice(name.length).matchAll(ATTRIBUTE)) {
        attrs[match[1]] = decodeXml(match[3] ?? match[4]);
      }
      const node = { name, attrs, children: [], text: '' };
      top.children.push(node);
      if (!selfClosing) {
        stack.push(node);
      }
    } else {
      top.text += token;
    }
  }
  if (stack.length !== 1 || root.children.length !== 1) {
    throw new Error('Malformed XML: unclosed element or no root');
  }
  return root.children[0];
}

/** The first child element named `name`, or null. */
export const child = (node, name) => node?.children.find((entry) => entry.name === name) ?? null;

/** Every child element named `name`. */
export const childrenNamed = (node, name) =>
  node ? node.children.filter((entry) => entry.name === name) : [];

/** Text of the first child named `name`: null when absent, '' when empty. */
export const textOf = (node, name) => child(node, name)?.text ?? null;

/** Integer value of the first child named `name`, or null when absent, empty or not a number. */
export function intOf(node, name) {
  const text = textOf(node, name);
  if (text === null || text === '' || !/^-?\d+$/.test(text)) {
    return null;
  }
  return Number(text);
}
